style.css:
:root {
  --bg-color: #1a1622;        /* nền tím xám nhẹ */
  --text-color: #f5f0fa;
  --main-color: #ffb6d9;      /* hồng pastel */
  --secondary-color: #ffd6ec; /* hồng rất nhạt */
  --accent-color: #ffc2e2;
}

/* nền */
body {
  background-color: var(--bg-color);
  color: var(--text-color);
}

/* link */
a {
  color: var(--main-color);
}
a:hover {
  color: var(--secondary-color);
}

/* code block */
code, pre {
  background: #241c2e;
  color: #ffe4f2;
  border-radius: 10px;
}

/* button */
button {
  background: var(--main-color);
  color: #4a2b3a;
  border: none;
  border-radius: 10px;
}
button:hover {
  background: var(--accent-color);
}

/* scrollbar */
::-webkit-scrollbar-thumb {
  background: var(--main-color);
  border-radius: 10px;
}
